// Low-level bech32 primitives, replicating sipa's reference implementation.

export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';

const GENERATOR = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

export function hrpExpand(hrp) {
  const ret = [];
  for (let i = 0; i < hrp.length; i++) {
    ret.push(hrp.charCodeAt(i) >> 5);
  }
  ret.push(0);
  for (let i = 0; i < hrp.length; i++) {
    ret.push(hrp.charCodeAt(i) & 31);
  }
  return ret;
}

export function polymod(values) {
  let chk = 1;
  for (let v = 0; v < values.length; v++) {
    const value = values[v];
    const top = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ value;
    for (let i = 0; i < 5; i++) {
      chk ^= ((top >> i) & 1) !== 0 ? GENERATOR[i] : 0;
    }
  }
  return chk;
}

export function verifyChecksum(hrp, data) {
  const pm = polymod(hrpExpand(hrp).concat(data));
  if (pm === 1) return 'bech32';
  if (pm === 0x2bc830a3) return 'bech32m';
  return null;
}

export function bech32Decode(bech) {
  if (bech.length > 90) return [null, null];
  let hasLower = false;
  let hasUpper = false;
  for (let i = 0; i < bech.length; i++) {
    const c = bech.charCodeAt(i);
    if (c < 33 || c > 126) return [null, null];
    if (c >= 97 && c <= 122) hasLower = true;
    if (c >= 65 && c <= 90) hasUpper = true;
  }
  if (hasLower && hasUpper) return [null, null];
  const bechLower = bech.toLowerCase();
  const pos = bechLower.lastIndexOf('1');
  if (pos < 1 || pos + 7 > bechLower.length) return [null, null];
  const hrp = bechLower.slice(0, pos);
  const dataPart = bechLower.slice(pos + 1);
  const data = [];
  for (let i = 0; i < dataPart.length; i++) {
    const v = CHARSET.indexOf(dataPart[i]);
    if (v === -1) return [null, null];
    data.push(v);
  }
  // Replicates sipa exactly: returns the FULL data part INCLUDING the 6
  // checksum chars. Checksum validation is done by the caller via
  // verifyChecksum.
  return [hrp, data];
}

// General power-of-2 base conversion, replicating sipa's convertbits.

export function convertbits(data, frombits, tobits, pad = true) {
  let acc = 0;
  let bits = 0;
  const ret = [];
  const maxv = (1 << tobits) - 1;
  const maxAcc = (1 << (frombits + tobits - 1)) - 1;
  for (let i = 0; i < data.length; i++) {
    const value = data[i];
    if (value < 0 || value >> frombits !== 0) return null;
    acc = ((acc << frombits) | value) & maxAcc;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      ret.push((acc >> bits) & maxv);
    }
  }
  if (pad) {
    if (bits > 0) {
      ret.push((acc << (tobits - bits)) & maxv);
    }
  } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv) !== 0) {
    return null;
  }
  return ret;
}

// Segwit address decoding, replicating sipa's segwit_addr.decode.

import { bech32Decode, verifyChecksum } from './encoding.mjs';
import { convertbits } from './convertbits.mjs';

export { convertbits } from './convertbits.mjs';

export function decode(hrp, addr) {
  const [hrpgot, data] = bech32Decode(addr);
  if (hrpgot !== hrp) return [null, null];
  const spec = verifyChecksum(hrpgot, data);
  if (spec === null) return [null, null];
  // Strip the 6-char checksum from the data returned by bech32Decode.
  const payload = data.slice(0, data.length - 6);
  const decoded = convertbits(payload.slice(1), 5, 8, false);
  if (decoded === null || decoded.length < 2 || decoded.length > 40) {
    return [null, null];
  }
  if (payload[0] > 16) return [null, null];
  if (payload[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
    return [null, null];
  }
  if ((payload[0] === 0 && spec !== 'bech32') ||
      (payload[0] !== 0 && spec !== 'bech32m')) {
    return [null, null];
  }
  return [payload[0], decoded];
}

