node --input-type=module -e "
import { decode, convertbits } from '/output/bech32/decode.mjs';

// 1. valid v0 address
const [v, p] = decode('bc', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4');
console.log('v0:', v, 'len:', p && p.length, 'first3:', p && p.slice(0,3));
console.log('convertbits 5->8 on witprog:', convertbits(p, 5, 8));

// 2. uppercase address with lowercase hrp
console.log('upper:', decode('bc', 'BC1QW508D6QEJXTDG4Y5R3ZARVARY0C5XW7KV8F3T4')[0]);

// 3. mixed case
console.log('mixed:', decode('bc', 'bc1Qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4'));

// 4. bad checksum
console.log('badchk:', decode('bc', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kg3g4ty'));

// 5. four sample inputs -> [null, null]
console.log('s1:', decode('bc', 'bc1p6xlxuzj6dwac8v78ka6eqhwj3sn60q6zqpfh542'));
console.log('s2:', decode('test', 'test14da5wycjddx3y6m55vvrllz3688u25'));
console.log('s3:', decode('ltc', 'ltc1slh4n8xqg4hhh03dc9xg8zvvuxy4n7vf'));
console.log('s4:', decode('tb', 'tb1eywca9kaaax9txemve4y54ld783azf7fd5zcrhm'));

// 6. taproot address
const [tv, tp] = decode('bc', 'bc1p5d7rjq7g6rdk2yhzks9smlaqtedr4dekq08ge8ztwac72sfr9rusxgysqe');
console.log('taproot:', tv, 'len:', tp && tp.length);
"

node --input-type=module -e "
import { bech32Decode, verifyChecksum, polymod, hrpExpand } from '/output/bech32/encoding.mjs';
import { convertbits } from '/output/bech32/convertbits.mjs';
const addr = 'bc1p5d7rjq7g6rdk2yhzks9smlaqtedr4dekq08ge8ztwac72sfr9rusxgysqe';
const [hrp, data] = bech32Decode(addr);
console.log('hrp:', hrp, 'len:', data.length, 'v0:', data[0]);
console.log('spec:', verifyChecksum(hrp, data));
console.log('polymod:', polymod(hrpExpand(hrp).concat(data)).toString(16));
const payload = data.slice(0, -6);
