console.log('b350-1:', decode('bc', 'bc1p38j9r5y49hruaue7wxjce0updqjuyyx0kh56v8s25huc6995vvpql3jow4').map(x => Array.isArray(x) ? 'arr'+x.length : x));
console.log('b350-2:', decode('tb', 'tb1p38j9r5y49hruaue7wxjce0updqjuyyx0kh56v8s25huc6995vvpg32y8wf').map(x => Array.isArray(x) ? 'arr'+x.length : x));
console.log('b350-3:', decode('bc', 'bc1gmk9yu').map(x => Array.isArray(x) ? 'arr'+x.length : x));
