node --input-type=module -e "
import { polymod, hrpExpand, CHARSET, verifyChecksum } from '/output/bech32/encoding.mjs';
// BIP-350: 'A1LQFN3A' is a valid bech32m string, hrp='a'
const data = 'lqfn3a'.split('').map(c => CHARSET.indexOf(c));
const pm = polymod(hrpExpand('a').concat(data));
console.log('pm:', pm.toString(16), 'expect 2bc830a3');
console.log('verify:', verifyChecksum('a', data));
// And BIP-173 vector: 'a12uel5l' valid bech32, hrp='a'
const d2 = '2uel5l'.split('').map(c => CHARSET.indexOf(c));
console.log('pm2:', polymod(hrpExpand('a').concat(d2)).toString(16), 'expect 1');
"

node --input-type=module -e "
import { hrpExpand, polymod, CHARSET } from '/output/bech32/encoding.mjs';
import { convertbits } from '/output/bech32/convertbits.mjs';
function createChecksum(hrp, data, spec) {
  const c = spec === 'bech32m' ? 0x2bc830a3 : 1;
  const values = hrpExpand(hrp).concat(data).concat([0,0,0,0,0,0]);
  const pm = polymod(values) ^ c;
  const ret = [];
  for (let p = 0; p < 6; p++) ret.push((pm >> (5 * (5 - p))) & 31);
  return ret;
}
function encode(hrp, witver, progBytes) {
  const spec = witver === 0 ? 'bech32' : 'bech32m';
  const data = [witver].concat(convertbits(progBytes, 8, 5, true));
  const combined = data.concat(createChecksum(hrp, data, spec));
  return hrp + '1' + combined.map(d => CHARSET[d]).join('');
}
// taproot v1, 32 zero bytes
const tp = encode('bc', 1, new Array(32).fill(0));
console.log(tp);
// v0 20 zero bytes
console.log(encode('bc', 0, new Array(20).fill(0)));
" > /tmp/addrs.txt && cat /tmp/addrs.txt && while read a; do echo "== $a"; /workspace/dataset/test12_executable --a bc --b "$a"; echo "exit=$?"; done < /tmp/addrs.txt

