import { decode, convertbits } from '/output/bech32/decode.mjs';
function script(hrp, addr) {
  const [witver, witprog] = decode(hrp, addr);
  if (witver === null) return; // prints nothing, like the Python script
  console.log(witver);
  const r = convertbits(witprog, 5, 8);
  console.log(r === null ? 'None' : r);
}
script('bc', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4');   // expect 0 / None
